  String title="Mi animación"; File work; Handler handler=new Handler(Looper.getMainLooper()); DrawView drawing; LinearLayout root, timeline; TextView status, frameCount; Button audioListButton, onionButton, playButton; Spinner rateSpinner; SeekBar scrub; MediaRecorder recorder; File recordingFile;
