  static class Sprite {String file; float x,y,w,h; Sprite(String f,float px,float py,float sw,float sh){file=f;x=px;y=py;w=sw;h=sh;} Sprite copy(){return new Sprite(file,x,y,w,h);}}
  ArrayList<Sprite> copySprites(ArrayList<Sprite> src){ArrayList<Sprite> out=new ArrayList<>();for(Sprite s:src)out.add(s.copy());return out;}
  Runnable tick=new Runnable(){public void run(){if(!playing)return;current=(current+1)%frames.size();drawing.invalidate();refreshTimeline();handler.postDelayed(this,1000/fps);}};

  @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(Color.rgb(23,23,29));getWindow().setNavigationBarColor(Color.rgb(23,23,29));work=new File(getFilesDir(),"TrazoVivo");work.mkdirs();frames.add(blank());spriteFrames.add(new ArrayList<>());buildUI();}
  Bitmap blank(){Bitmap b=Bitmap.createBitmap(W,H,Bitmap.Config.ARGB_8888);b.eraseColor(Color.WHITE);return b;}
  Bitmap spriteBitmap(String path){try{BitmapFactory.Options o=new BitmapFactory.Options();o.inSampleSize=1;return BitmapFactory.decodeFile(path,o);}catch(Exception e){return null;}}
  Bitmap renderFrame(int index){Bitmap out=frames.get(index).copy(Bitmap.Config.ARGB_8888,true);Canvas c=new Canvas(out);for(Sprite sp:spriteFrames.get(index)){Bitmap b=spriteBitmap(sp.file);if(b!=null){c.drawBitmap(b,null,new RectF(sp.x,sp.y,sp.x+sp.w,sp.y+sp.h),new Paint(Paint.ANTI_ALIAS_FLAG|Paint.FILTER_BITMAP_FLAG));b.recycle();}}return out;}
