  void menu(){String[] opts={"Nuevo proyecto","Abrir proyecto","Guardar proyecto","Exportar video MP4","Ayuda"};new AlertDialog.Builder(this).setTitle("Trazo Vivo").setItems(opts,(d,n)->{switch(n){case 0:newProject();break;case 1:openProject();break;case 2:saveProject();break;case 3:exportVideo();break;case 4:help();}}).show();}
  void help(){new AlertDialog.Builder(this).setTitle("Cómo animar").setMessage("Dibujá cuadro por cuadro. Guía ✓ muestra el anterior. Mover dibujo: rodeá una zona para volverla un objeto que puedas arrastrar. Mover imagen permite reubicar imágenes importadas. Mantené apretada una miniatura para duplicarla, reordenarla o borrarla. ▶ reproduce la secuencia. Agregá una pista de audio o grabá voz; Exportar MP4 crea un video en tu teléfono. Guardá el proyecto para seguir editándolo luego.").setPositiveButton("Entendido",null).show();}
  class DrawView extends View {Paint p=new Paint(3);ArrayList<Bitmap> undo=new ArrayList<>();float lastX,lastY;boolean moved;
    float downX,downY,origX,origY,origW,origH,initialGap,selectStartX,selectStartY; RectF selectionRect; int movingIndex=-1; DrawView(Context c){super(c);setLayerType(View.LAYER_TYPE_SOFTWARE,null);}
    void pushUndo(){Bitmap cp=frames.get(current).copy(Bitmap.Config.ARGB_8888,true);undo.add(cp);if(undo.size()>15){undo.remove(0).recycle();}}
    void clearUndo(){for(Bitmap b:undo)if(!b.isRecycled())b.recycle();undo.clear();}
    void undo(){if(!undo.isEmpty()){Bitmap old=frames.set(current,undo.remove(undo.size()-1));if(old!=null&&!old.isRecycled())old.recycle();invalidate();refreshTimeline();}}
    protected void onDraw(Canvas c){super.onDraw(c);c.drawColor(Color.WHITE);float scale=Math.min(getWidth()/(float)W,getHeight()/(float)H);float dx=(getWidth()-W*scale)/2,dy=(getHeight()-H*scale)/2;c.save();c.translate(dx,dy);c.scale(scale,scale);if(onion&&frames.size()>1){int prev=(current-1+frames.size())%frames.size();Paint op=new Paint(3);op.setAlpha(96);c.drawBitmap(frames.get(prev),0,0,op);for(Sprite ghost:spriteFrames.get(prev)){Bitmap gb=spriteBitmap(ghost.file);if(gb!=null){Paint gp=new Paint(Paint.ANTI_ALIAS_FLAG|Paint.FILTER_BITMAP_FLAG);gp.setAlpha(75);c.drawBitmap(gb,null,new RectF(ghost.x,ghost.y,ghost.x+ghost.w,ghost.y+ghost.h),gp);gb.recycle();}}}c.drawBitmap(frames.get(current),0,0,null);if(selectionRect!=null){Paint marquee=new Paint(3);marquee.setColor(Color.rgb(255,64,129));marquee.setStyle(Paint.Style.STROKE);marquee.setStrokeWidth(2);marquee.setPathEffect(new DashPathEffect(new float[]{6,4},0));c.drawRect(selectionRect,marquee);}for(int si=0;si<spriteFrames.get(current).size();si++){Sprite sp=spriteFrames.get(current).get(si);Bitmap sb=spriteBitmap(sp.file);if(sb!=null){c.drawBitmap(sb,null,new RectF(sp.x,sp.y,sp.x+sp.w,sp.y+sp.h),new Paint(Paint.ANTI_ALIAS_FLAG|Paint.FILTER_BITMAP_FLAG));sb.recycle();if(moveMode&&si==selectedSprite){Paint edge=new Paint(3);edge.setColor(Color.rgb(103,80,164));edge.setStyle(Paint.Style.STROKE);edge.setStrokeWidth(2);c.drawRect(sp.x,sp.y,sp.x+sp.w,sp.y+sp.h,edge);}}}c.restore();}
    public boolean onTouchEvent(android.view.MotionEvent e){float scale=Math.min(getWidth()/(float)W,getHeight()/(float)H);float dx=(getWidth()-W*scale)/2,dy=(getHeight()-H*scale)/2;float x=(e.getX()-dx)/scale,y=(e.getY()-dy)/scale;int action=e.getActionMasked();if(action==MotionEvent.ACTION_DOWN){if(x<0||y<0||x>W||y>H)return false;downX=x;downY=y;lastX=x;lastY=y;moved=false;if(selectDrawingMode){selectionRect=new RectF(x,y,x,y);selectStartX=x;selectStartY=y;invalidate();return true;}if(moveMode){movingIndex=-1;ArrayList<Sprite> list=spriteFrames.get(current);for(int i=list.size()-1;i>=0;i--){Sprite sp=list.get(i);if(x>=sp.x&&x<=sp.x+sp.w&&y>=sp.y&&y<=sp.y+sp.h){movingIndex=i;selectedSprite=i;origX=sp.x;origY=sp.y;origW=sp.w;origH=sp.h;break;}}invalidate();}else pushUndo();return true;}if(action==MotionEvent.ACTION_POINTER_DOWN&&moveMode&&e.getPointerCount()>=2){if(movingIndex>=0){Sprite sp=spriteFrames.get(current).get(movingIndex);origW=sp.w;origH=sp.h;initialGap=gap(e);downX=x;downY=y;}return true;}if(action==MotionEvent.ACTION_MOVE){if(selectDrawingMode&&selectionRect!=null){selectionRect.set(Math.min(selectStartX,x),Math.min(selectStartY,y),Math.max(selectStartX,x),Math.max(selectStartY,y));invalidate();return true;}if(moveMode){if(movingIndex>=0){Sprite sp=spriteFrames.get(current).get(movingIndex);if(e.getPointerCount()>=2&&initialGap>0){float factor=gap(e)/initialGap;float nw=Math.max(24,Math.min(W,origW*factor)),nh=Math.max(24,Math.min(H,origH*factor));sp.x=origX+(origW-nw)/2;sp.y=origY+(origH-nh)/2;sp.w=nw;sp.h=nh;}else{sp.x=Math.max(0,Math.min(W-sp.w,origX+(x-downX)));sp.y=Math.max(0,Math.min(H-sp.h,origY+(y-downY)));}moved=true;invalidate();}return true;}if(x<0||y<0||x>W||y>H){lastX=x;lastY=y;return true;}Canvas cc=new Canvas(frames.get(current));Paint line=new Paint(3);line.setColor(eraser?Color.WHITE:color);line.setStrokeWidth(eraser?brush*3:brush);line.setStrokeCap(Paint.Cap.ROUND);line.setStrokeJoin(Paint.Join.ROUND);line.setStyle(Paint.Style.STROKE);cc.drawLine(lastX,lastY,x,y,line);lastX=x;lastY=y;moved=true;invalidate();return true;}if(action==MotionEvent.ACTION_UP||action==MotionEvent.ACTION_POINTER_UP){if(action==MotionEvent.ACTION_UP){if(selectDrawingMode&&selectionRect!=null){Rect r=new Rect(Math.max(0,(int)selectionRect.left),Math.max(0,(int)selectionRect.top),Math.min(W,(int)Math.ceil(selectionRect.right)),Math.min(H,(int)Math.ceil(selectionRect.bottom)));selectionRect=null;selectDrawingMode=false;if(selectButton!=null)selectButton.setText("Mover dibujo");if(r.width()>3&&r.height()>3){Bitmap crop=Bitmap.createBitmap(frames.get(current),r.left,r.top,r.width(),r.height()).copy(Bitmap.Config.ARGB_8888,true);int[] px=new int[crop.getWidth()*crop.getHeight()];crop.getPixels(px,0,crop.getWidth(),0,0,crop.getWidth(),crop.getHeight());for(int pi=0;pi<px.length;pi++){if(Color.red(px[pi])>238&&Color.green(px[pi])>238&&Color.blue(px[pi])>238)px[pi]=Color.TRANSPARENT;}crop.setPixels(px,0,crop.getWidth(),0,0,crop.getWidth(),crop.getHeight());File sf=new File(work,"draw_"+System.currentTimeMillis()+".png");try(FileOutputStream fo=new FileOutputStream(sf)){crop.compress(Bitmap.CompressFormat.PNG,100,fo);Canvas wipe=new Canvas(frames.get(current));Paint white=new Paint();white.setColor(Color.WHITE);wipe.drawRect(r,white);spriteFrames.get(current).add(new Sprite(sf.getAbsolutePath(),r.left,r.top,r.width(),r.height()));moveMode=true;if(moveButton!=null)moveButton.setText("Mover: sí");selectedSprite=spriteFrames.get(current).size()-1;status.setText("Dibujo seleccionado: arrastralo para ubicarlo y duplicá cuadros para animarlo.");}catch(Exception ex){toast("No pude convertir la selección en un dibujo movible.");}crop.recycle();}invalidate();refreshTimeline();return true;}if(!moveMode&&!moved){Canvas cc=new Canvas(frames.get(current));Paint dot=new Paint(3);dot.setColor(eraser?Color.WHITE:color);cc.drawCircle(x,y,(eraser?brush*3:brush)/2f,dot);invalidate();}if(moveMode&&movingIndex>=0){if(!moved)showSpriteOptions(movingIndex);movingIndex=-1;}return true;}}return true;}
    float gap(MotionEvent e){if(e.getPointerCount()<2)return 0;float xx=e.getX(0)-e.getX(1),yy=e.getY(0)-e.getY(1);return (float)Math.sqrt(xx*xx+yy*yy);}
  }
  void addFrame(){drawing.clearUndo();if(frames.size()>=120){toast("Máximo 120 cuadros para cuidar la memoria del teléfono.");return;}stopPlay();int at=Math.min(current+1,frames.size());frames.add(at,blank());spriteFrames.add(at,copySprites(spriteFrames.get(current)));current=at;drawing.invalidate();refreshTimeline();}
  void duplicateFrame(){drawing.clearUndo();if(frames.size()>=120){toast("Máximo 120 cuadros para cuidar la memoria del teléfono.");return;}stopPlay();Bitmap cp=frames.get(current).copy(Bitmap.Config.ARGB_8888,true);frames.add(current+1,cp);spriteFrames.add(current+1,copySprites(spriteFrames.get(current)));current++;drawing.invalidate();refreshTimeline();}
  void deleteFrame(){drawing.clearUndo();if(frames.size()==1){frames.get(0).eraseColor(Color.WHITE);drawing.invalidate();return;}frames.remove(current).recycle();spriteFrames.remove(current);current=Math.min(current,frames.size()-1);drawing.invalidate();refreshTimeline();}
  void moveFrame(int from,int to){if(from<0||to<0||from>=frames.size()||to>=frames.size()||from==to)return;Bitmap b=frames.remove(from);ArrayList<Sprite> ss=spriteFrames.remove(from);frames.add(to,b);spriteFrames.add(to,ss);current=to;drawing.invalidate();refreshTimeline();}
  void refreshTimeline(){if(timeline==null)return;timeline.removeAllViews();for(int i=0;i<frames.size();i++){final int index=i;ImageView im=new ImageView(this);im.setImageBitmap(frames.get(i));im.setScaleType(ImageView.ScaleType.FIT_CENTER);im.setBackgroundColor(i==current?Color.rgb(103,80,164):Color.rgb(48,48,56));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(dp(75),dp(55));p.setMargins(dp(3),dp(4),dp(3),dp(4));im.setPadding(dp(2),dp(2),dp(2),dp(2));im.setContentDescription("Cuadro "+(i+1));im.setOnLongClickListener(v->{new AlertDialog.Builder(this).setItems(new String[]{"Duplicar cuadro","Mover antes","Mover después","Eliminar cuadro"},(d,n)->{current=index;if(n==0)duplicateFrame();else if(n==1)moveFrame(index,Math.max(0,index-1));else if(n==2)moveFrame(index,Math.min(frames.size()-1,index+1));else deleteFrame();}).show();return true;});im.setOnClickListener(v->{stopPlay();drawing.clearUndo();current=index;drawing.invalidate();refreshTimeline();});timeline.addView(im,p);}if(frameCount!=null)frameCount.setText("Cuadros · "+frames.size());if(scrub!=null){scrub.setMax(Math.max(0,frames.size()-1));scrub.setProgress(current);}}
  void togglePlay(){if(playing)stopPlay();else{if(frames.size()<2)return;playing=true;if(playButton!=null)playButton.setText("⏸");handler.post(tick);}}
  void stopPlay(){playing=false;handler.removeCallbacks(tick);if(playButton!=null)playButton.setText("▶");}
  void newProject(){new AlertDialog.Builder(this).setTitle("¿Proyecto nuevo?").setMessage("Se borrará el trabajo que no hayas guardado.").setNegativeButton("Cancelar",null).setPositiveButton("Nuevo",(d,w)->{stopPlay();frames.clear();frames.add(blank());spriteFrames.clear();spriteFrames.add(new ArrayList<>());current=0;audioPaths.clear();audioNames.clear();refreshAudioButton();title="Mi animación";drawing.invalidate();refreshTimeline();}).show();}
  void pickImage(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("image/*");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,PICK_IMAGE);}
  void importImage(Uri uri){try{File f=new File(work,"img_"+System.currentTimeMillis()+".png");BitmapFactory.Options bounds=new BitmapFactory.Options();bounds.inJustDecodeBounds=true;try(InputStream in=getContentResolver().openInputStream(uri)){BitmapFactory.decodeStream(in,null,bounds);}int sw=Math.max(1,bounds.outWidth),sh=Math.max(1,bounds.outHeight);int sample=1;while(sw/sample>900||sh/sample>900)sample*=2;BitmapFactory.Options opt=new BitmapFactory.Options();opt.inSampleSize=sample;Bitmap bm;try(InputStream in=getContentResolver().openInputStream(uri)){bm=BitmapFactory.decodeStream(in,null,opt);}if(bm==null)throw new IOException("Formato de imagen no compatible.");FileOutputStream out=new FileOutputStream(f);bm.compress(Bitmap.CompressFormat.PNG,95,out);out.close();float ratio=Math.min(220f/bm.getWidth(),180f/bm.getHeight());float ww=bm.getWidth()*ratio,hh=bm.getHeight()*ratio;bm.recycle();spriteFrames.get(current).add(new Sprite(f.getAbsolutePath(),(W-ww)/2,(H-hh)/2,ww,hh));moveMode=true;if(moveButton!=null)moveButton.setText("Mover: sí");selectedSprite=spriteFrames.get(current).size()-1;drawing.invalidate();status.setText("Imagen lista: arrastrala para moverla; dos dedos para cambiar su tamaño.");}catch(Exception e){toast("No pude importar esa imagen.");}}
  void showSpriteOptions(int index){if(index<0||index>=spriteFrames.get(current).size())return;new AlertDialog.Builder(this).setTitle("Imagen").setItems(new String[]{"Traer al frente","Duplicar en este cuadro","Quitar de este cuadro"},(d,n)->{ArrayList<Sprite> list=spriteFrames.get(current);Sprite sp=list.get(index);if(n==0){list.remove(index);list.add(sp);}else if(n==1){list.add(sp.copy());}else{list.remove(index);}selectedSprite=-1;drawing.invalidate();}).show();}
  void pickAudio(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("audio/*");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,PICK_AUDIO);}
  @Override protected void onActivityResult(int request,@Nullable int result,@Nullable Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK||data==null||data.getData()==null)return;Uri uri=data.getData();if(request==PICK_AUDIO){copyAudio(uri);}else if(request==PICK_IMAGE){importImage(uri);}else if(request==SAVE_PROJECT){writeProject(uri);}else if(request==OPEN_PROJECT){readProject(uri);}else if(request==SAVE_VIDEO){new Thread(()->encodeVideo(uri)).start();}}
  String displayName(Uri u){String n="audio";try(android.database.Cursor c=getContentResolver().query(u,null,null,null,null)){if(c!=null&&c.moveToFirst()){int k=c.getColumnIndex(OpenableColumns.DISPLAY_NAME);if(k>=0)n=c.getString(k);}}catch(Exception ignored){}return n;}
  void copyAudio(Uri u){try{String n=displayName(u);File f=new File(work,System.currentTimeMillis()+"_"+n.replaceAll("[^A-Za-z0-9._-]","_"));try(InputStream in=getContentResolver().openInputStream(u);OutputStream out=new FileOutputStream(f)){byte[] b=new byte[8192];int z;while((z=in.read(b))>0)out.write(b,0,z);}audioPaths.add(f.getAbsolutePath());audioNames.add(n);status.setText("Audio agregado: "+n);refreshAudioButton();showAudio();}catch(Exception e){toast("No pude abrir ese audio.");}}
  void refreshAudioButton(){if(audioListButton!=null)audioListButton.setText("♫ "+audioPaths.size());}
  void showAudio(){if(audioPaths.isEmpty()){new AlertDialog.Builder(this).setMessage("Todavía no hay pistas. Agregá un archivo de audio o grabá tu voz.").setPositiveButton("Agregar audio",(d,w)->pickAudio()).show();return;}String[] a=new String[audioPaths.size()+1];for(int i=0;i<audioPaths.size();i++)a[i]=audioNames.get(i);a[a.length-1]="Listo";new AlertDialog.Builder(this).setTitle("Audio del proyecto").setItems(a,(d,n)->{if(n<audioPaths.size())new AlertDialog.Builder(this).setMessage(audioNames.get(n)+"\nSe incluirá en MP4 solo si está codificado en AAC/M4A; el MP4 usa una sola pista.").setNegativeButton("Cerrar",null).setPositiveButton("Quitar",(dd,ww)->{audioPaths.remove(n);audioNames.remove(n);refreshAudioButton();showAudio();}).show();}).show();}
  void toggleRecord(){if(recorder!=null){try{recorder.stop();recorder.release();}catch(Exception ignored){}recorder=null;if(recordingFile!=null&&recordingFile.length()>1000){audioPaths.add(recordingFile.getAbsolutePath());audioNames.add("Voz grabada");refreshAudioButton();status.setText("Voz grabada y agregada al proyecto.");}return;}if(ContextCompat.checkSelfPermission(this,Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED){ActivityCompat.requestPermissions(this,new String[]{Manifest.permission.RECORD_AUDIO},REQ_MIC);return;}try{recordingFile=new File(work,"voz_"+System.currentTimeMillis()+".m4a");recorder=new MediaRecorder();recorder.setAudioSource(MediaRecorder.AudioSource.MIC);recorder.setOutputFormat(MediaRecorder.OutputFormat.MPEG_4);recorder.setAudioEncoder(MediaRecorder.AudioEncoder.AAC);recorder.setAudioSamplingRate(44100);recorder.setAudioEncodingBitRate(96000);recorder.setOutputFile(recordingFile.getAbsolutePath());recorder.prepare();recorder.start();status.setText("Grabando voz… tocá 🎙 Voz para terminar.");}catch(Exception e){if(recorder!=null){recorder.release();recorder=null;}toast("No se pudo iniciar la grabación.");}}
  void saveProject(){Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.setType("application/zip");i.putExtra(Intent.EXTRA_TITLE,(title.isEmpty()?"TrazoVivo":title)+".tvproj");startActivityForResult(i,SAVE_PROJECT);}
  JSONObject projectMeta()throws Exception{JSONObject o=new JSONObject();o.put("title",title);o.put("fps",fps);o.put("current",current);JSONArray a=new JSONArray();for(int i=0;i<audioNames.size();i++){JSONObject x=new JSONObject();x.put("name",audioNames.get(i));x.put("file","audio/"+i+".m4a");a.put(x);}o.put("audio",a);JSONArray allSprites=new JSONArray();for(int fi=0;fi<spriteFrames.size();fi++){JSONArray each=new JSONArray();for(int si=0;si<spriteFrames.get(fi).size();si++){Sprite sp=spriteFrames.get(fi).get(si);JSONObject so=new JSONObject();so.put("frame",fi);so.put("index",si);so.put("x",sp.x);so.put("y",sp.y);so.put("w",sp.w);so.put("h",sp.h);so.put("file","images/"+new File(sp.file).getName());each.put(so);}allSprites.put(each);}o.put("sprites",allSprites);o.put("width",W);o.put("height",H);o.put("frames",frames.size());return o;}
  void writeProject(Uri uri){try(OutputStream raw=getContentResolver().openOutputStream(uri);ZipOutputStream z=new ZipOutputStream(new BufferedOutputStream(raw))){z.putNextEntry(new ZipEntry("project.json"));z.write(projectMeta().toString().getBytes("UTF-8"));z.closeEntry();for(int i=0;i<frames.size();i++){z.putNextEntry(new ZipEntry("frames/"+i+".png"));frames.get(i).compress(Bitmap.CompressFormat.PNG,100,z);z.closeEntry();}HashSet<String> savedImages=new HashSet<>();for(ArrayList<Sprite> list:spriteFrames)for(Sprite sp:list){String entry="images/"+new File(sp.file).getName();if(savedImages.add(entry)){z.putNextEntry(new ZipEntry(entry));try(InputStream in=new FileInputStream(sp.file)){byte[] b=new byte[8192];int n;while((n=in.read(b))>0)z.write(b,0,n);}z.closeEntry();}}for(int i=0;i<audioPaths.size();i++){z.putNextEntry(new ZipEntry("audio/"+i+".m4a"));try(InputStream in=new FileInputStream(audioPaths.get(i))){byte[] b=new byte[8192];int n;while((n=in.read(b))>0)z.write(b,0,n);}z.closeEntry();}status.setText("Proyecto guardado en tu teléfono.");toast("Proyecto guardado.");}catch(Exception e){toast("No se pudo guardar el proyecto.");}}
  void openProject(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("application/zip");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,OPEN_PROJECT);}
  void readProject(Uri uri){try{File temp=new File(work,"import.zip");try(InputStream in=getContentResolver().openInputStream(uri);OutputStream out=new FileOutputStream(temp)){byte[] b=new byte[8192];int n;while((n=in.read(b))>0)out.write(b,0,n);}HashMap<String,byte[]> entries=new HashMap<>();try(ZipInputStream z=new ZipInputStream(new FileInputStream(temp))){ZipEntry e;byte[] buf=new byte[8192];while((e=z.getNextEntry())!=null){ByteArrayOutputStream o=new ByteArrayOutputStream();int n;while((n=z.read(buf))>0)o.write(buf,0,n);entries.put(e.getName(),o.toByteArray());}}JSONObject meta=new JSONObject(new String(entries.get("project.json"),"UTF-8"));ArrayList<Bitmap> nf=new ArrayList<>();for(int i=0;i<meta.getInt("frames");i++){byte[] b=entries.get("frames/"+i+".png");Bitmap q=BitmapFactory.decodeByteArray(b,0,b.length);Bitmap scaled=Bitmap.createScaledBitmap(q,W,H,true);if(q!=scaled)q.recycle();nf.add(scaled);}ArrayList<ArrayList<Sprite>> ns=new ArrayList<>();JSONArray spriteMeta=meta.optJSONArray("sprites");for(int fi=0;fi<nf.size();fi++){ArrayList<Sprite> list=new ArrayList<>();if(spriteMeta!=null&&fi<spriteMeta.length()){JSONArray each=spriteMeta.optJSONArray(fi);if(each!=null)for(int si=0;si<each.length();si++){JSONObject so=each.getJSONObject(si);String entry=so.getString("file");byte[] image=entries.get(entry);if(image!=null){File im=new File(work,"loaded_img_"+System.currentTimeMillis()+"_"+fi+"_"+si+".png");try(FileOutputStream fout=new FileOutputStream(im)){fout.write(image);}list.add(new Sprite(im.getAbsolutePath(),(float)so.getDouble("x"),(float)so.getDouble("y"),(float)so.getDouble("w"),(float)so.getDouble("h")));}}}ns.add(list);}ArrayList<String> ap=new ArrayList<>(),an=new ArrayList<>();JSONArray a=meta.optJSONArray("audio");if(a!=null)for(int i=0;i<a.length();i++){JSONObject x=a.getJSONObject(i);byte[] bytes=entries.get(x.getString("file"));if(bytes!=null){File f=new File(work,"loaded_"+System.currentTimeMillis()+"_"+i+".m4a");try(FileOutputStream o=new FileOutputStream(f)){o.write(bytes);}ap.add(f.getAbsolutePath());an.add(x.getString("name"));}}stopPlay();for(Bitmap q:frames)q.recycle();frames.clear();frames.addAll(nf);spriteFrames.clear();spriteFrames.addAll(ns);audioPaths.clear();audioPaths.addAll(ap);audioNames.clear();audioNames.addAll(an);refreshAudioButton();title=meta.optString("title","Mi animación");fps=meta.optInt("fps",8);if(rateSpinner!=null){int[] rates={4,6,8,10,12,15};int match=2;for(int ri=0;ri<rates.length;ri++)if(rates[ri]==fps)match=ri;rateSpinner.setSelection(match);}current=Math.min(meta.optInt("current",0),frames.size()-1);drawing.invalidate();refreshTimeline();status.setText("Proyecto abierto: "+title);}catch(Exception e){toast("No pude abrir ese proyecto; quizá esté dañado.");}}
  void exportVideo(){if(frames.isEmpty())return;Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.setType("video/mp4");i.putExtra(Intent.EXTRA_TITLE,"TrazoVivo.mp4");startActivityForResult(i,SAVE_VIDEO);}
  void encodeVideo(Uri output){runOnUiThread(()->status.setText("Preparando video…"));MediaCodec codec=null;MediaMuxer mux=null;File tmp=new File(work,"video_silent.mp4");try{int width=W,height=H;MediaFormat fmt=MediaFormat.createVideoFormat(MediaFormat.MIMETYPE_VIDEO_AVC,width,height);fmt.setInteger(MediaFormat.KEY_COLOR_FORMAT,MediaCodecInfo.CodecCapabilities.COLOR_FormatYUV420SemiPlanar);fmt.setInteger(MediaFormat.KEY_BIT_RATE,1200000);fmt.setInteger(MediaFormat.KEY_FRAME_RATE,fps);fmt.setInteger(MediaFormat.KEY_I_FRAME_INTERVAL,1);codec=MediaCodec.createEncoderByType(MediaFormat.MIMETYPE_VIDEO_AVC);codec.configure(fmt,null,null,MediaCodec.CONFIGURE_FLAG_ENCODE);codec.start();mux=new MediaMuxer(tmp.getAbsolutePath(),MediaMuxer.OutputFormat.MUXER_OUTPUT_MPEG_4);MediaCodec.BufferInfo info=new MediaCodec.BufferInfo();long pts=0;int dur=1000000/fps;EncState encState=new EncState();
    for(int fi=0;fi<frames.size();fi++){Bitmap composed=renderFrame(fi);byte[] yuv=bitmapToYuv(composed);composed.recycle();int in=codec.dequeueInputBuffer(10000);while(in<0){drain(codec,mux,info,encState);in=codec.dequeueInputBuffer(10000);}ByteBuffer buf=codec.getInputBuffer(in);buf.clear();buf.put(yuv);codec.queueInputBuffer(in,0,yuv.length,pts,0);pts+=dur;drain(codec,mux,info,encState);}
    int in=codec.dequeueInputBuffer(10000);while(in<0){drain(codec,mux,info,encState);in=codec.dequeueInputBuffer(10000);}codec.queueInputBuffer(in,0,0,pts,MediaCodec.BUFFER_FLAG_END_OF_STREAM);boolean done=false;while(!done){int ix=codec.dequeueOutputBuffer(info,10000);if(ix==MediaCodec.INFO_TRY_AGAIN_LATER)continue;if(ix==MediaCodec.INFO_OUTPUT_FORMAT_CHANGED){if(!encState.started){encState.track=mux.addTrack(codec.getOutputFormat());mux.start();encState.started=true;}}else if(ix>=0){ByteBuffer out=codec.getOutputBuffer(ix);if(info.size>0&&encState.started){out.position(info.offset);out.limit(info.offset+info.size);mux.writeSampleData(encState.track,out,info);}done=(info.flags&MediaCodec.BUFFER_FLAG_END_OF_STREAM)!=0;codec.releaseOutputBuffer(ix,false);}}
    codec.stop();codec.release();codec=null;if(!encState.started)throw new IOException("El codificador no generó una pista de video.");mux.stop();mux.release();mux=null;
    boolean withAudio=false;if(!audioPaths.isEmpty()){try{withAudio=tryMuxAudio(tmp,output,audioPaths.get(0),frames.size()*1000000L/fps);}catch(Exception audioError){withAudio=false;}}
    if(!withAudio)try(OutputStream o=getContentResolver().openOutputStream(output);InputStream in2=new FileInputStream(tmp)){if(o==null)throw new IOException("No se pudo crear el archivo de salida.");byte[] b=new byte[8192];int n;while((n=in2.read(b))>0)o.write(b,0,n);}tmp.delete();final boolean exportedAudio=withAudio;runOnUiThread(()->{status.setText(exportedAudio?"MP4 exportado con una pista de audio AAC.":(audioPaths.isEmpty()?"MP4 exportado sin audio.":"MP4 exportado sin audio: pista incompatible o no disponible."));toast("Video guardado.");});
  }catch(Exception ex){if(codec!=null){try{codec.stop();}catch(Exception ignored){}codec.release();}if(mux!=null){try{mux.release();}catch(Exception ignored){}}tmp.delete();String msg=ex.getMessage();runOnUiThread(()->{status.setText("Falló la exportación.");new AlertDialog.Builder(this).setTitle("No se pudo exportar").setMessage(msg==null?"Error de video":msg).setPositiveButton("Cerrar",null).show();});}}
  static class EncState {int track=-1;boolean started=false;}
  void drain(MediaCodec codec,MediaMuxer mux,MediaCodec.BufferInfo info,EncState state)throws Exception{while(true){int ix=codec.dequeueOutputBuffer(info,0);if(ix==MediaCodec.INFO_TRY_AGAIN_LATER)return;if(ix==MediaCodec.INFO_OUTPUT_FORMAT_CHANGED){if(!state.started){state.track=mux.addTrack(codec.getOutputFormat());mux.start();state.started=true;}}else if(ix>=0){ByteBuffer out=codec.getOutputBuffer(ix);if(info.size>0&&state.started){out.position(info.offset);out.limit(info.offset+info.size);mux.writeSampleData(state.track,out,info);}boolean eos=(info.flags&MediaCodec.BUFFER_FLAG_END_OF_STREAM)!=0;codec.releaseOutputBuffer(ix,false);if(eos)return;}}}
  byte[] bitmapToYuv(Bitmap b){int w=b.getWidth(),h=b.getHeight();int[] argb=new int[w*h];b.getPixels(argb,0,w,0,0,w,h);byte[] out=new byte[w*h*3/2];int yIndex=0,uvIndex=w*h;for(int j=0;j<h;j++)for(int i=0;i<w;i++){int c=argb[j*w+i],r=(c>>16)&255,g=(c>>8)&255,bl=c&255;int y=((66*r+129*g+25*bl+128)>>8)+16;int u=((-38*r-74*g+112*bl+128)>>8)+128;int v=((112*r-94*g-18*bl+128)>>8)+128;out[yIndex++]=(byte)Math.max(0,Math.min(255,y));if((j&1)==0&&(i&1)==0){out[uvIndex++]=(byte)Math.max(0,Math.min(255,u));out[uvIndex++]=(byte)Math.max(0,Math.min(255,v));}}return out;}
  static class PendingSample {byte[] data;long pts;int flags;boolean valid;}
  PendingSample nextSample(MediaExtractor ex,ByteBuffer buffer,long maxPts)throws IOException{PendingSample s=new PendingSample();int n=ex.readSampleData(buffer,0);if(n<0)return s;s.pts=ex.getSampleTime();if(s.pts>maxPts)return s;s.flags=ex.getSampleFlags();s.data=new byte[n];buffer.position(0);buffer.get(s.data,0,n);s.valid=true;ex.advance();return s;}
  boolean tryMuxAudio(File video,Uri output,String audio,long durationUs)throws Exception{File muxed=new File(work,"with_audio.mp4");if(muxed.exists())muxed.delete();MediaExtractor vx=new MediaExtractor(),ax=new MediaExtractor();MediaMuxer m=null;boolean started=false;try{vx.setDataSource(video.getAbsolutePath());ax.setDataSource(audio);int vi=-1,ai=-1;MediaFormat vf=null,af=null;for(int i=0;i<vx.getTrackCount();i++){MediaFormat f=vx.getTrackFormat(i);String mime=f.getString(MediaFormat.KEY_MIME);if(mime!=null&&mime.startsWith("video/")){vi=i;vf=f;break;}}for(int i=0;i<ax.getTrackCount();i++){MediaFormat f=ax.getTrackFormat(i);String mime=f.getString(MediaFormat.KEY_MIME);if("audio/mp4a-latm".equals(mime)){ai=i;af=f;break;}}if(vi<0||ai<0)return false;vx.selectTrack(vi);ax.selectTrack(ai);m=new MediaMuxer(muxed.getAbsolutePath(),MediaMuxer.OutputFormat.MUXER_OUTPUT_MPEG_4);int vt=m.addTrack(vf),at=m.addTrack(af);m.start();started=true;int maxV=Math.max(1024*1024,vf.containsKey(MediaFormat.KEY_MAX_INPUT_SIZE)?vf.getInteger(MediaFormat.KEY_MAX_INPUT_SIZE):0);int maxA=Math.max(1024*1024,af.containsKey(MediaFormat.KEY_MAX_INPUT_SIZE)?af.getInteger(MediaFormat.KEY_MAX_INPUT_SIZE):0);ByteBuffer vb=ByteBuffer.allocate(maxV),ab=ByteBuffer.allocate(maxA);PendingSample vs=nextSample(vx,vb,Long.MAX_VALUE),as=nextSample(ax,ab,durationUs);MediaCodec.BufferInfo bi=new MediaCodec.BufferInfo();while(vs.valid||as.valid){boolean videoNext=!as.valid||(vs.valid&&vs.pts<=as.pts);PendingSample q=videoNext?vs:as;bi.set(0,q.data.length,q.pts,q.flags);m.writeSampleData(videoNext?vt:at,ByteBuffer.wrap(q.data),bi);if(videoNext)vs=nextSample(vx,vb,Long.MAX_VALUE);else as=nextSample(ax,ab,durationUs);}m.stop();started=false;m.release();m=null;try(OutputStream o=getContentResolver().openOutputStream(output);InputStream in=new FileInputStream(muxed)){if(o==null)throw new IOException("No se pudo crear el MP4.");byte[] b=new byte[8192];int n;while((n=in.read(b))>0)o.write(b,0,n);}return true;}finally{if(m!=null){if(started){try{m.stop();}catch(Exception ignored){}}m.release();}vx.release();ax.release();muxed.delete();}}
  void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
